/**
 * Remove falsy values from object
 */
export const removeFalsy = (obj) => Object.fromEntries(Object.entries(obj).filter(([, value]) => isTruthy(value)));
export const removeUndefined = (obj) => Object.fromEntries(Object.entries(obj).filter(([, value]) => isDefined(value)));
export const isTruthy = (value) => isDefined(value) && (typeof value !== 'string' || value.trim() !== '');
export const isDefined = (value) => value !== undefined && value !== null;
